// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type MapCategoriesProps = Record<string, any>;

const MapCategories: React.FC<MapCategoriesProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "The Map",
  subtitle = "5 Categories",
  primaryAccentColor = "#38bdf8",
  textColor = "#f8fafc",
  categories = ["1", "2", "3", "4", "5"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe background color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing Configuration
  const introDuration = 45;
  const holdDuration = 30;
  const wipeStart = introDuration + holdDuration;
  const wipeDuration = 35;

  // Title Animations (Intro)
  const titleTranslateY = interpolate(
    spring({ frame, fps, config: { damping: 14, mass: 1.2 } }),
    [0, 1],
    [100, 0]
  );
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const subtitleTranslateY = interpolate(
    spring({ frame: frame - 10, fps, config: { damping: 14 } }),
    [0, 1],
    [50, 0]
  );
  const subtitleOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Wipe Transition Logic
  const wipeProgress = interpolate(
    frame,
    [wipeStart, wipeStart + wipeDuration],
    [0, 1],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  // Layout Dimensions
  const circleSize = height * 0.18;
  const fontSize = height * 0.08;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* SCENE 1: Title Card */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          fontFamily: playfairFamily,
        }}
      >
        <div
          style={{
            transform: `translateY(${titleTranslateY}px)`,
            opacity: titleOpacity,
            fontSize: height * 0.15,
            fontWeight: 700,
            color: textColor,
            lineHeight: 1.1,
            transition: "none",
          }}
        >
          {title}
        </div>
        <div
          style={{
            transform: `translateY(${subtitleTranslateY}px)`,
            opacity: subtitleOpacity,
            fontSize: height * 0.04,
            fontWeight: 500,
            color: primaryAccentColor,
            fontFamily: interFamily,
            letterSpacing: "0.2em",
            textTransform: "uppercase",
            marginTop: height * 0.02,
            transition: "none",
          }}
        >
          {subtitle}
        </div>
      </AbsoluteFill>

      {/* SCENE 2: Categories (Revealed by Wipe) */}
      <AbsoluteFill
        style={{
          clipPath: `inset(0 ${100 - wipeProgress * 100}% 0 0)`,
          backgroundColor: bgColor, // Covers Scene 1
          transition: "none",
        }}
      >
        <AbsoluteFill
          style={{
            flexDirection: "row",
            justifyContent: "center",
            alignItems: "center",
            gap: width * 0.04,
            padding: `0 ${width * 0.05}px`,
          }}
        >
          {categories.map((item, index) => {
            // Trigger pop animation based on when the wipe passes this element's physical position
            const itemRevealProgressFrame =
              wipeStart + (wipeDuration * (index + 0.5)) / categories.length;
            const pop = spring({
              frame: frame - itemRevealProgressFrame,
              fps,
              config: { damping: 12, mass: 0.8 },
            });

            return (
              <div
                key={index}
                style={{
                  width: circleSize,
                  height: circleSize,
                  borderRadius: "50%",
                  border: `4px solid ${primaryAccentColor}`,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${pop})`,
                  backgroundColor: `${primaryAccentColor}1A`, // 10% opacity hex
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontFamily: interFamily,
                    fontSize: fontSize,
                    fontWeight: 800,
                    color: textColor,
                  }}
                >
                  {item}
                </span>
              </div>
            );
          })}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* WIPE LINE */}
      {wipeProgress > 0 && wipeProgress < 1 && (
        <AbsoluteFill
          style={{
            width: width * 0.01,
            height: "100%",
            backgroundColor: primaryAccentColor,
            left: `${wipeProgress * 100}%`,
            boxShadow: `0 0 ${width * 0.02}px ${primaryAccentColor}`,
            transform: "translateX(-50%)",
            transition: "none",
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default MapCategories;